WHERE h.DELETED_YN = 'N'
AND l.DELETED_YN = 'N'

	AND h.BUSINESS_DATE >= TO_DATE(#{startDate}, 'YYYY-MM-DD')


	AND h.BUSINESS_DATE < TO_DATE(#{endDate}, 'YYYY-MM-DD') + 1


	AND h.PROGRESS_STATUS = #{progressStatus}


	AND UPPER(l.SPECIFICATION) LIKE '%' || UPPER(TRIM(#{specification})) ||
	'%'


	AND h.WAREHOUSE_ID IN

		#{warehouseId}



	AND h.PARTNER_ID IN

		#{partnerId}



	AND l.ITEM_ID IN

		#{itemId}



	AND h.ASSIGNEE_ID IN

		#{assigneeId}



	AND l.QUANTITY >= #{minQuantity}


	AND l.QUANTITY <= #{maxQuantity}


	AND l.UNIT_PRICE >= #{minUnitPrice}


	AND l.UNIT_PRICE <= #{maxUnitPrice}


	AND l.SUPPLY_AMOUNT >= #{minSupplyAmount}


	AND l.SUPPLY_AMOUNT <= #{maxSupplyAmount}


	AND l.VAT_AMOUNT >= #{minVatAmount}


	AND l.VAT_AMOUNT <= #{maxVatAmount}


	AND (
	UPPER(h.SALE_NO) LIKE '%' || UPPER(TRIM(#{keyword})) || '%'
	OR TO_CHAR(h.BUSINESS_DATE, 'YYYY-MM-DD') LIKE '%' || TRIM(#{keyword})
	|| '%'
	OR TO_CHAR(h.BUSINESS_DATE, 'YYYY/MM/DD') LIKE '%' || TRIM(#{keyword})
	|| '%'
	OR UPPER(i.ITEM_CODE) LIKE '%' || UPPER(TRIM(#{keyword})) || '%'
	OR UPPER(l.ITEM_NAME) LIKE '%' || UPPER(TRIM(#{keyword})) || '%'
	OR UPPER(l.SPECIFICATION) LIKE '%' || UPPER(TRIM(#{keyword})) || '%'
	OR UPPER(l.UNIT) LIKE '%' || UPPER(TRIM(#{keyword})) || '%'
	OR UPPER(h.PARTNER_NAME) LIKE '%' || UPPER(TRIM(#{keyword})) || '%'
	OR UPPER(h.WAREHOUSE_NAME) LIKE '%' || UPPER(TRIM(#{keyword})) || '%'
	OR UPPER(h.ASSIGNEE_NAME) LIKE '%' || UPPER(TRIM(#{keyword})) || '%'
	OR UPPER(h.NOTE) LIKE '%' || UPPER(TRIM(#{keyword})) || '%'
	OR UPPER(l.NOTE) LIKE '%' || UPPER(TRIM(#{keyword})) || '%'
	)
